local function a(b)function b.IsUnitValid(c)if c==nil then return false end;local d,e=pcall(function()return not c:IsNull()end)if not d or not e then return false end;return true end;function b.GetHP(c)if not b.IsUnitValid(c)or not c:CanBeSeen()or not c:IsAlive()then return 0 end;local f=c:GetHealth()local g=c:GetMaxHealth()if GetTeam()==c:GetTeam()then f=c:OriginalGetHealth()g=c:OriginalGetMaxHealth()end;if f<=0 then return 0 end;return f/g end;function b.GetMP(h)if not b.IsUnitValid(h)then return 0 end;if h:GetUnitName()=='npc_dota_hero_huskar'then return h:GetHealth()/h:GetMaxHealth()end;return h:GetMana()/h:GetMaxMana()end;function b.GetManaAfter(i)local h=GetBot()return(h:GetMana()-i)/h:GetMaxMana()end;function b.GetHealthAfter(j)local h=GetBot()return(h:GetHealth()-j)/h:GetMaxHealth()end;function b.GetOne(k)return math.floor(k*10)/10 end;function b.ToNearest500(l)return math.floor(l/500+0.5)*500 end;function b.CombineTwoTable(m,n)local o=m;local p=#m;for q,r in pairs(n)do o[p+q]=r end;return o end;function b.CheckBitfieldFlag(s,t)return s/t%2>=1 end;function b.GetETAWithAcceleration(u,v,w)return(math.sqrt(2*w*u+v*v)-v)/w end;local x={}function b.HasNotActionLast(y,z)if x[z]==nil then x[z]=-90 end;if DotaTime()>x[z]+y then x[z]=DotaTime()return true end;return false end;function b.CountNotStunnedUnits(A,B,C,D)local E=0;if B.count>=D then for F,c in pairs(A)do if GetUnitToLocationDistance(c,B.targetloc)<=C and not c:IsInvulnerable()and not b.IsDisabled(c)then E=E+1 end end end;return E end;function b.HasHealingItem(h)return b.HasItem(h,"item_tango")or b.HasItem(h,"item_tango_single")or b.HasItem(h,"item_flask")or b.HasItem(h,"item_bottle")or b.HasItem(h,"item_faerie_fire")or b.HasItem(h,"item_enchanted_mango")or b.HasItem(h,"item_famango")or b.HasItem(h,"item_great_famango")or b.HasItem(h,"item_greater_famango")or h:HasModifier("modifier_tango_heal")or h:HasModifier("modifier_flask_healing")or h:HasModifier("modifier_bottle_regeneration")end end;return a